using namespace std;
// With at most one region, blocking a cell makes 3 regions exactly when it is the middle of
// "ooo" in its row and the other row reads "xox" in the same three columns.
int main(){ int n; string a, b; cin >> n >> a >> b; long long ans = 0;
  for(int k = 0; k < 2; k++){ const string &r = k ? b : a, &o = k ? a : b;
    for(int i = 1; i + 1 < n; i++)
      if(r[i-1] == 'o' && r[i] == 'o' && r[i+1] == 'o' && o[i-1] == 'x' && o[i] == 'o' && o[i+1] == 'x') ans++; }
  cout << ans << "\n"; }
